package org.apache.commons.cli2.commandline;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Properties;
import java.util.Set;
import org.apache.commons.cli2.Argument;
import org.apache.commons.cli2.Option;
import org.apache.commons.cli2.WriteableCommandLine;
import org.apache.commons.cli2.commandline.WriteableCommandLineImpl;
import org.apache.commons.cli2.option.PropertyOption;
import org.apache.commons.cli2.resource.ResourceConstants;
import org.apache.commons.cli2.resource.ResourceHelper;
import org.apache.commons.cli2.util.Lists;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class WriteableCommandLineImpl_getValues_TriageGen0Test {

    @Test
    public void testGetValues_NullOption() {
        // Arrange
        WriteableCommandLineImpl impl = new WriteableCommandLineImpl(null, Lists.newArrayList());

        // Act
        List result = impl.getValues(null, Lists.newArrayList());

        // Assert
        assertNotNull(result);
    }

    @Test
    public void testGetValues_NullDefaultValues() {
        // Arrange
        WriteableCommandLineImpl impl = new WriteableCommandLineImpl(new Option("test"), Lists.newArrayList());

        // Act
        List result = impl.getValues(new Option("test"), null);

        // Assert
        assertNotNull(result);
    }

    @Test
    public void testGetValues_NoValueList() {
        // Arrange
        WriteableCommandLineImpl impl = new WriteableCommandLineImpl(new Option("test"), Lists.newArrayList());

        // Act
        List result = impl.getValues(new Option("test"), Lists.newArrayList());

        // Assert
        assertNotNull(result);
        assertTrue(result.isEmpty());
    }

    @Test
    public void testGetValues_ValueListReturned() {
        // Arrange
        WriteableCommandLineImpl impl = new WriteableCommandLineImpl(new Option("test"), Lists.newArrayList());
        List valueList = Lists.newArrayList("value1", "value2");

        // Act
        impl.values.put(new Option("test"), valueList);
        List result = impl.getValues(new Option("test"), Lists.newArrayList());

        // Assert
        assertNotNull(result);
        assertEquals(valueList, result);
    }

    @Test
    public void testGetValues_DefaultValuesReturned() {
        // Arrange
        WriteableCommandLineImpl impl = new WriteableCommandLineImpl(new Option("test"), Lists.newArrayList());
        List defaultValues = Lists.newArrayList("defValue1", "defValue2");

        // Act
        impl.defaultValues.put(new Option("test"), defaultValues);
        List result = impl.getValues(new Option("test"), Lists.newArrayList());

        // Assert
        assertNotNull(result);
        assertEquals(defaultValues, result);
    }

    @Test
    public void testGetValues_ValueListAndDefaultValuesReturned() {
        // Arrange
        WriteableCommandLineImpl impl = new WriteableCommandLineImpl(new Option("test"), Lists.newArrayList());
        List valueList = Lists.newArrayList("value1", "value2");
        List defaultValues = Lists.newArrayList("defValue1", "defValue2");

        // Act
        impl.values.put(new Option("test"), valueList);
        impl.defaultValues.put(new Option("test"), defaultValues);
        List result = impl.getValues(new Option("test"), Lists.newArrayList());

        // Assert
        assertNotNull(result);
        assertEquals(valueList, result);
    }

    @Test
    public void testGetValues_MoreDefaultValuesReturned() {
        // Arrange
        WriteableCommandLineImpl impl = new WriteableCommandLineImpl(new Option("test"), Lists.newArrayList());
        List defaultValues = Lists.newArrayList("defValue1", "defValue2");
        List moreDefaultValues = Lists.newArrayList("moreDefValue1", "moreDefValue2");

        // Act
        impl.defaultValues.put(new Option("test"), defaultValues);
        impl.defaultValues.put(new Option("test"), moreDefaultValues);
        List result = impl.getValues(new Option("test"), Lists.newArrayList());

        // Assert
        assertNotNull(result);
        assertEquals(moreDefaultValues, result);
    }

    @Test
    public void testGetValues_NullValueList() {
        // Arrange
        WriteableCommandLineImpl impl = new WriteableCommandLineImpl(new Option("test"), Lists.newArrayList());
        List valueList = null;

        // Act
        impl.values.put(new Option("test"), valueList);
        List result = impl.getValues(new Option("test"), Lists.newArrayList());

        // Assert
        assertNotNull(result);
        assertTrue(result.isEmpty());
    }
}
